import java.util.*;

class Solution {
    public int majorityElement(int[] votes) {
        int cand = 0, count = 0;
        for (int v : votes) {
            if (count == 0) cand = v;        // start a new candidate
            count += (v == cand) ? 1 : -1;   // same vote supports, different vote cancels
        }
        return cand;                         // a majority is guaranteed to survive
    }
}

